#include <cstddef>
#include <vector>
#include <omp.h>

size_t findFirstEven(std::vector<int> const& x) {
    const size_t n = x.size();
    size_t first = n;  // If no even value exists, return x.size().

    #pragma omp parallel for reduction(min:first) schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); ++i) {
        const size_t idx = static_cast<size_t>(i);
        if ((x[idx] % 2) == 0 && idx < first) {
            first = idx;
        }
    }

    return first;
}
